def proposal(what_en, what_fr, origin=ORIGIN, status_enum=PROPOSAL):
    """The four fields every proposal carries. origin is ORIGIN for every table except LandingRelation.
    status_enum is PROPOSAL for every table except MatchPlan (MATCH_PLAN_STATUS, adds SUPERSEDED) - kept as a
    parameter, not a MatchPlan-only special case, so the next LLM-proposed row that needs its own extra status
    (reviewComment's own field-naming convention - see that field's own comment) can reuse this same hook."""
    return [
        F('origin', en='Origin', fr='Origine', min=1, default='USER', enum=origin,
          desc_en='Who proposed this %s: a deterministic rule, the language model, or a person.' % what_en,
          desc_fr='Qui a proposé %s : une règle déterministe, le modèle de langage ou une personne.' % what_fr),
        F('confidence', 'int', en='Confidence (%)', fr='Confiance (%)',
          desc_en='0 to 100. Empty for a line entered by a person.', desc_fr='De 0 à 100. Vide pour une ligne saisie par une personne.'),
        F('rationale', 'text', en='Rationale', fr='Justification', maxLen=2000,
          desc_en='Why it was proposed: the rule that fired, or the explanation given by the model.',
          desc_fr='Pourquoi la proposition a été faite : la règle déclenchée, ou l\'explication donnée par le modèle.'),
        F('status', en='Status', fr='Statut', min=1, default='PROPOSED', enum=status_enum,
          desc_en='Nothing is generated from a line that is not accepted.', desc_fr="Rien n'est généré depuis une ligne qui n'est pas acceptée."),
    ]


def encrypted(f):
    # osd:password with the default editor stores an irreversible SHA-512 hash: a secret read back needs EBX's reversible encryption
    f.encryptionClass = 'com.orchestranetworks.security.PasswordTypeEncryption'
    return f


