    T('MatchPlan', 'Matching plans', 'Plans de rapprochement', ['id'], [
        F('id', 'id', en='Id', fr='Id', min=1),
        F('entity', en='Entity', fr='Entité', fk='/root/StagingEntity', min=1),
        # 2026-10-12 (fix/match-plan-requirements-length): 4000 -> 100000. This JSON is parsed back (configure, review tree), so a writer must
        # store it whole or not at all (master.StoredJsonFit); 4000 cut a 14-node Person plan on Vol100kM. Keep StoredJsonFit.REQUIREMENTS_MAX_LENGTH in step.
        F('requirements', 'text', en='Requirements', fr='Exigences', maxLen=100000,
          desc_en='What makes two records the same, in plain words; handed to the Match and Merge policy generator.',
          desc_fr="Ce qui fait que deux enregistrements sont le même, en clair ; transmis au générateur de politique de Match and Merge."),
        F('matchingPolicy', en='Matching policy', fr='Politique de rapprochement', maxLen=80),
        F('mergePolicy', en='Merge policy', fr='Politique de fusion', maxLen=80),
        F('autoMerge', 'boolean', en='Merge matches without review?', fr='Fusionner sans revue ?', default='false',
          desc_en='false: every match is routed to the suspects, a data steward confirms each merge.', desc_fr='false : chaque correspondance passe en suspect, un data steward confirme chaque fusion.'),
        # review-match-plan lot (2026-09-22): the SAME numbers CrossSystemFieldGuard already computes, structured
        # instead of folded only into the prose of `rationale` below - see master.MatchPlanEvidence for the exact
        # JSON shape. Generated/refreshed by both MatchPlanLlmSuggester and MatchPlanSuggester whenever they
        # write/refresh a plan; empty for a plan written before this field existed (review.MatchPlanView then
        # says so rather than guessing).
        F('evidence', 'text', en='Evidence (JSON)', fr='Preuve (JSON)', maxLen=100000,
          desc_en='One entry per field the plan mentions or considered: role, cross-system sharing, per-system fill, verdict - the structured sibling of the prose already folded into rationale.',
          desc_fr="Une entrée par champ mentionné ou envisagé par le plan : rôle, partage entre systèmes, remplissage par système, verdict - la version structurée de la prose déjà repliée dans rationale."),
    ] + proposal('matching plan', 'le plan de rapprochement', status_enum=MATCH_PLAN_STATUS) + [
        F('message', 'text', en='Message', fr='Message', maxLen=2000),
        # ------------------------------------------------------------------------------- reject/repropose lot (2026-09-22)
        # Free-text reviewer comment on a REJECTED or SUPERSEDED plan, handed back to the language model when a new
        # proposal is requested (ebx.MatchPlanLlmSuggester / master.MatchPlanLlmPass) - see docs/MATCHING.md "Review
        # feedback". Same field name is meant to extend, unchanged, to every other LLM-proposed row (StagingEntity/
        # StagingAttribute/AttributeMapping/QualityRule/CapabilitySuggestion) once this loop is built for them too.
        F('reviewComment', 'text', en='Review comment', fr='Commentaire de revue', maxLen=2000,
          desc_en='Why the plan was set aside (SUPERSEDED) or ruled out entirely (REJECTED) - passed to the language model when a new proposal is requested.',
          desc_fr="Pourquoi le plan a été mis de côté (SUPERSEDED) ou écarté définitivement (REJECTED) - transmis au modèle de langage lors d'une nouvelle proposition."),
        # "Propose another" never discards the superseded plan's own requirements - kept here so nothing is lost even
        # though the row's own requirements field is about to be overwritten by the new proposal (or left untouched
        # if the pass fails/returns nothing/repeats the same plan - see ebx.MatchPlanLlmSuggester).
        F('previousRequirements', 'text', en='Previous requirements', fr='Exigences précédentes', maxLen=100000,
          desc_en='The requirements JSON of the plan just superseded by a new proposal - kept so nothing is lost.',
          desc_fr="Le JSON d'exigences du plan tout juste remplacé par une nouvelle proposition - conservé pour ne rien perdre."),
    ], label='${./entity}', desc_en='How the records of an entity are matched and merged in the master zone.', desc_fr="Comment les enregistrements d'une entité sont rapprochés et fusionnés dans la zone MDM."),

