def render():
    out = [HEADER.rstrip('\n')]
    for t in TABLES:
        out.append('')
        out += table(t, '                ')
    out.append(FOOTER.rstrip('\n'))
    return '\n'.join(out) + '\n'


# <xsd base name>_toolbars.xml, next to the XSD - the module-file convention for a MODULE (not DMA)
# model's toolbars (CLAUDE.md sec 6 "A DMA model's toolbars..."). EBX resolves a <tabularViewTop>/
# <tabularViewRow>/<recordTop> reference by NAME at render time and stays completely silent on a
# mismatch in either direction (no toolbar shown, no error, no compile/publish failure) - so this is
# the one automated guard against that trap. Always read from THIS repository's own checked-in copy,
# never from EBX_WORKSPACE/OUT - that variable only redirects where the regenerated XSD is written
# (tools/test_local.sh points it at a scratch folder to diff against the committed XSD), and the
# toolbars file itself is static, never regenerated, so it would not exist there.
TOOLBARS_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..',
                              'ebx-mdm-factory/src/main/webapp/WEB-INF/ebx/schemas/MdmFactory_toolbars.xml')


def check_toolbar_names():
    """Every toolbar name a table's T(..., toolbars={...}) references must exist as a <toolbar><name> in
    MdmFactory_toolbars.xml, and every <toolbar><name> in that file must be referenced by some table -
    an orphaned toolbar body is exactly as silent a bug as a dangling reference (it simply never shows
    up anywhere an author would notice). Raises SystemExit with both mismatches listed, if any."""
    import xml.etree.ElementTree as ET
    referenced = set()
    for t in TABLES:
        if getattr(t, 'toolbars', None):
            referenced.update(t.toolbars.values())
    root = ET.parse(TOOLBARS_FILE).getroot()
    declared = {node.text for node in root.iter('name') if node.text}
    missing = sorted(referenced - declared)
    orphaned = sorted(declared - referenced)
    if missing or orphaned:
        msg = ['toolbar name mismatch between build_xsd.py TABLES and %s:' % TOOLBARS_FILE]
        if missing:
            msg.append('  referenced by a table but not declared in the toolbars file: %s' % ', '.join(missing))
        if orphaned:
            msg.append('  declared in the toolbars file but never referenced by a table: %s' % ', '.join(orphaned))
        sys.exit('\n'.join(msg))


if __name__ == '__main__':
    check_toolbar_names()
    xsd = render()
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, 'w', encoding='utf-8') as f:
        f.write(xsd)
    print('%s: %d lines, %d tables' % (OUT, xsd.count('\n'), len(TABLES)))
